import{_ as t,o as e,c as l,a2 as i}from"./chunks/framework.CDU0sSpB.js";const u=JSON.parse('{"title":"前端与移动体验","description":"Hearth 的前端设计原则、信息架构、任务卡、审批、产物中心、手机端、可访问性与体验指标。","frontmatter":{"title":"前端与移动体验","description":"Hearth 的前端设计原则、信息架构、任务卡、审批、产物中心、手机端、可访问性与体验指标。","outline":[2,3]},"headers":[],"relativePath":"architecture/frontend-experience.md","filePath":"architecture/frontend-experience.md","lastUpdated":1793706118000}'),r={name:"architecture/frontend-experience.md"};function o(n,a,d,h,s,p){return e(),l("div",null,[...a[0]||(a[0]=[i('<p class="eyebrow">FRONTEND &amp; MOBILE</p><h1 id="前端与移动体验" tabindex="-1">前端与移动体验 <a class="header-anchor" href="#前端与移动体验" aria-label="Permalink to &quot;前端与移动体验&quot;">​</a></h1><p class="lead">用户只需要知道三件事：Agent 在做什么、是否需要我、下一步点哪里。前端不是后置包装层。</p><h2 id="前端与移动端体验" tabindex="-1">前端与移动端体验 <a class="header-anchor" href="#前端与移动端体验" aria-label="Permalink to &quot;前端与移动端体验&quot;">​</a></h2><p>Hearth 的前端不是展示 Agent 内部架构的控制台，而是安静的注意力界面。</p><h3 id="设计原则" tabindex="-1">设计原则 <a class="header-anchor" href="#设计原则" aria-label="Permalink to &quot;设计原则&quot;">​</a></h3><ol><li><strong>任务优先</strong>：用户看到要完成的事，不是模型、工具和线程；</li><li><strong>一个状态一个主动作</strong>：任务卡任何时刻只有一个最值得点击的动作；</li><li><strong>渐进披露</strong>：默认只显示目标、状态、证据和下一步；</li><li><strong>安静默认</strong>：没有需要人的事情就不打扰；</li><li><strong>状态诚实</strong>：不把运行中伪装成即将完成，不把模型说完成显示成已完成；</li><li><strong>手机对等</strong>：手机能完成查看、审批、接管、发起和通知；</li><li><strong>无内部术语</strong>：主界面不出现 Worker、Harness、Token、Mandate；</li><li><strong>界面先出现</strong>：每个增量先明确用户看到什么、能点什么、失败后怎么恢复，再接后端实现。</li></ol><p>前端不是后端完成后的展示层，而是产品纵向切片的一部分。第一阶段用原型验证信息架构，并在 MVP 中用真实页面连接真实状态；之后每个阶段都把新增能力呈现为可操作界面。功能只有在浏览器中有完整用户路径、证据和恢复入口，才算进入阶段验收。</p><h3 id="信息架构" tabindex="-1">信息架构 <a class="header-anchor" href="#信息架构" aria-label="Permalink to &quot;信息架构&quot;">​</a></h3><p>主导航保持四项：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>今日  |  需要你  |  产物  |  设置</span></span></code></pre></div><ul><li><strong>今日</strong>：正在做、刚完成、接下来要做什么；</li><li><strong>需要你</strong>：审批、补充信息、失败接管和异常；</li><li><strong>产物</strong>：报告、文档、代码、表格、截图、回执；</li><li><strong>设置</strong>：连接、记忆、权限、设备、通知和预算。</li></ul><p>“新任务”是全局动作，不占导航项。桌面端使用 <code>⌘K</code> / <code>Ctrl+K</code>，移动端使用明显悬浮按钮。</p><h3 id="首页" tabindex="-1">首页 <a class="header-anchor" href="#首页" aria-label="Permalink to &quot;首页&quot;">​</a></h3><p>首屏回答：今天有什么、什么需要我、正在做什么、最近完成了什么。默认不展示 Token、模型名、执行器名、内部步骤和调试日志；需要时进入详情查看。</p><h3 id="任务卡" tabindex="-1">任务卡 <a class="header-anchor" href="#任务卡" aria-label="Permalink to &quot;任务卡&quot;">​</a></h3><p>任务卡应回答：</p><ul><li>这是什么任务？</li><li>现在进行到哪一步？</li><li>有没有产物或验证证据？</li><li>是否需要我？</li><li>我下一步能做什么？</li></ul><p>字段包括标题、状态、关键阶段进度、产物、验证、风险、主动作和时间。每个状态只有一个主动作。</p><h3 id="状态与主动作" tabindex="-1">状态与主动作 <a class="header-anchor" href="#状态与主动作" aria-label="Permalink to &quot;状态与主动作&quot;">​</a></h3><table tabindex="0"><thead><tr><th>状态</th><th>用户看到</th><th>主动作</th></tr></thead><tbody><tr><td>排队中</td><td>等待设备或时间</td><td>调整优先级</td></tr><tr><td>执行中</td><td>当前阶段</td><td>查看进度</td></tr><tr><td>等待审批</td><td>将要发生什么</td><td>审批</td></tr><tr><td>等待信息</td><td>缺少什么</td><td>补充信息</td></tr><tr><td>失败</td><td>原因和补救</td><td>恢复/重试/转人工</td></tr><tr><td>已完成</td><td>产物和验证</td><td>查看产物</td></tr></tbody></table><h3 id="需要你" tabindex="-1">需要你 <a class="header-anchor" href="#需要你" aria-label="Permalink to &quot;需要你&quot;">​</a></h3><p>“需要你”只收集真正阻塞人的事项：审批、补信息、失败接管、高风险确认。纯状态变化和可自动重试的失败不进入。</p><h3 id="审批界面" tabindex="-1">审批界面 <a class="header-anchor" href="#审批界面" aria-label="Permalink to &quot;审批界面&quot;">​</a></h3><p>审批卡必须让用户在十秒内判断：动作、账户、收件人/资源、附件和内容、可逆性、有效期、失败补偿。高风险动作显示真实范围、差异、二次确认和撤销方式。</p><h3 id="产物中心" tabindex="-1">产物中心 <a class="header-anchor" href="#产物中心" aria-label="Permalink to &quot;产物中心&quot;">​</a></h3><p>产物是可检查的交付物，不是附件列表：</p><ul><li>版本、来源任务和执行器；</li><li>生成时间、哈希和大小；</li><li>验证结果与证据；</li><li>预览、下载、复制链接；</li><li>与上一版 diff；</li><li>相关审批和回执；</li><li>删除、归档和导出。</li></ul><h3 id="详情与时间线" tabindex="-1">详情与时间线 <a class="header-anchor" href="#详情与时间线" aria-label="Permalink to &quot;详情与时间线&quot;">​</a></h3><p>详情页展示目标、约束、计划、关键工具调用、产物与验证、审批和回执、错误/重试/换路、预算与成本、关联记忆和技能。默认不展示模型内部思维过程；展示可审计事件、证据和决策原因。</p><h3 id="新任务" tabindex="-1">新任务 <a class="header-anchor" href="#新任务" aria-label="Permalink to &quot;新任务&quot;">​</a></h3><p>支持自然语言、文件和图片、项目/联系人/截止时间、自主级别和验收标准预览。用户只写“帮我整理一下”时，系统应生成可编辑任务卡，而不是立刻无边界执行。</p><h3 id="接管界面" tabindex="-1">接管界面 <a class="header-anchor" href="#接管界面" aria-label="Permalink to &quot;接管界面&quot;">​</a></h3><p>显示当前浏览器/桌面，明确说明需要用户做什么；暂停自动输入；允许操作、批注、补充信息；记录接管前后状态；支持交还、缩小范围和终止。</p><h3 id="通知" tabindex="-1">通知 <a class="header-anchor" href="#通知" aria-label="Permalink to &quot;通知&quot;">​</a></h3><p>只用于高信号事件：需要审批、补充信息、失败无法恢复、用户明确关心的完成、设备离线阻塞、安全异常。</p><p>规则：同一任务聚合、静默时段、先摘要后详情、推送脱敏、点击直达动作、关闭渠道后不得绕过、通知频率与任务价值一起评估。</p><h3 id="手机端" tabindex="-1">手机端 <a class="header-anchor" href="#手机端" aria-label="Permalink to &quot;手机端&quot;">​</a></h3><p>手机优先使用网页入口，第四阶段只承担五件事：</p><ol><li>查看任务与产物；</li><li>审批高风险动作；</li><li>接管异常任务；</li><li>发起新任务；</li><li>接收高信号通知。</li></ol><p>手机不应：默认运行完整 Agent、持有长期主凭据、直接暴露本地端口、后台无界执行高风险任务、用推送正文泄露敏感信息。</p><p>安全设计：安全隧道或推送中继、短期码和公钥配对、会话过期与生物识别、审批绑定 nonce/参数/过期时间、设备丢失可撤销、离线只读缓存不产生副作用。</p><h3 id="可访问性与性能" tabindex="-1">可访问性与性能 <a class="header-anchor" href="#可访问性与性能" aria-label="Permalink to &quot;可访问性与性能&quot;">​</a></h3><p>键盘完成主要流程；不只依赖颜色；屏幕阅读器和可访问性标签；减少动画和深色模式；首屏快速加载、长列表虚拟化；弱网显示缓存和明确状态；中英文不截断关键动作；单手操作时主动作在可达区域。</p><h3 id="体验指标" tabindex="-1">体验指标 <a class="header-anchor" href="#体验指标" aria-label="Permalink to &quot;体验指标&quot;">​</a></h3><ul><li>用户理解当前状态的时间；</li><li>从“需要你”到完成审批的时间；</li><li>审批误点率和撤销率；</li><li>每任务打断次数；</li><li>手机完成关键动作的成功率；</li><li>通知打开后的处理率；</li><li>找不到产物或恢复入口的次数。</li></ul><h2 id="与-mvp-的关系" tabindex="-1">与 MVP 的关系 <a class="header-anchor" href="#与-mvp-的关系" aria-label="Permalink to &quot;与 MVP 的关系&quot;">​</a></h2><p>MVP 必须让用户通过浏览器完成创建、查看、审批演练、取消、重试、恢复和取回产物。第一阶段先做可点击原型，再连接真实任务状态，最后达到完整 MVP。</p><p>没有真实 Web 路径的“MVP”不成立；没有失败态和恢复入口的界面也不算完成。</p>',49)])])}const b=t(r,[["render",o]]);export{u as __pageData,b as default};
